function all(paths){var out=[],reqs=[],rs=null,i;for(i=0;i<paths.length;i++)reqs.push({url:'https://raw.githubusercontent.com/huoguotiankong/asset-core-7f3/'+REF+'/'+paths[i],options:{timeout:6000,headers:{'Cache-Control':'public, max-age=31536000, immutable'}}});try{if(typeof batchFetch==='function')rs=batchFetch(reqs);}catch(e){rs=null;}for(i=0;i<paths.length;i++){var s=rs&&rs[i]!=null?String(rs[i]):'';if(!good(s))s=one(paths[i]);out.push(s);}return out;}
function meta(){try{if(!fileExist(META)||!fileExist(BUNDLE)||!fileExist(DECODER))return null;var m=parse(readFile(META),null);return m&&Number(m.build||0)===BUILD&&String(m.version||'')===VERSION&&String(m.sourceRef||'')===REF?m:null;}catch(e){return null;}}
function install(force){var old=meta();if(old&&!force)return old;var tx=all(MODULES),parts=[];for(var i=0;i<MODULES.length;i++)parts.push('\n/* ===== '+MODULES[i]+' ===== */\n'+tx[i]+'\n;\n');var bundle='/* ACFun '+VERSION+' generated Stable 0.4.9 runtime · '+REF+' */\n'+parts.join('');writeFile(BUNDLE,bundle);if(!fileExist(BUNDLE))throw new Error('Runtime bundle 写入失败');var dec=one(DECODER_PATH);writeFile(DECODER,dec);if(!fileExist(DECODER))throw new Error('ImageDecoder 写入失败');var m={schema:1,version:VERSION,build:BUILD,sourceRef:REF,modules:MODULES.length,bytes:bundle.length,imageDecoder:true,decoderBytes:dec.length,installedAt:Date.now(),bundle:BUNDLE,decoder:DECODER};writeFile(META,JSON.stringify(m));var back=meta();if(!back)throw new Error('bundle meta 回读失败');return back;}
function req(p){var u=getPath(p);try{require(u);}catch(e0){try{deleteCache(u);}catch(e1){}require(u);}}
function load(){var m=install(false);req(BUNDLE);if(typeof ac!=='object'||String(ac.localFirstVersion||'')!==VERSION||Number(ac.localFirstBuild||0)!==BUILD)throw new Error('ACFun Local-First runtime preflight failed');return m;}
function reset(){try{if(fileExist(BUNDLE))deleteFile(BUNDLE);}catch(e){}try{if(fileExist(DECODER))deleteFile(DECODER);}catch(e2){}try{if(fileExist(META))deleteFile(META);}catch(e3){}return true;}
return{version:VERSION,build:BUILD,sourceRef:REF,install:install,load:load,meta:meta,reset:reset,bundle:BUNDLE,decoder:DECODER,modules:MODULES};
